// Parse NLP processing request
const request = $input.first().json;

// Required fields validation
if (!request.text || !request.processing_type) {
  return [{
    json: {
      error: 'Missing required fields: text, processing_type',
      status: 'invalid'
    }
  }];
}

// Define processing configuration
const processingConfig = {
  text: request.text,
  processing_type: request.processing_type, // sentiment, intent, entities, summarization, etc.
  context: request.context || {},
  agent_id: request.agent_id || 'unknown',
  conversation_id: request.conversation_id || null,
  timestamp: new Date().toISOString(),
  options: {
    language: request.language || 'en',
    detail_level: request.detail_level || 'standard',
    include_confidence: request.include_confidence !== false,
    max_tokens: request.max_tokens || 1000
  }
};

return [{
  json: processingConfig
}];

// Prepare sentiment analysis prompt for DeepSeek
const config = $input.first().json;

const sentimentPrompt = `
You are an expert sentiment analyzer for AI agent communications. Analyze the following text and provide detailed sentiment analysis.

Text to analyze: "${config.text}"

Context: ${JSON.stringify(config.context, null, 2)}

Please provide a JSON response with the following structure:
{
  "sentiment": {
    "overall": "positive/negative/neutral",
    "confidence": 0.95,
    "scores": {
      "positive": 0.1,
      "negative": 0.8,
      "neutral": 0.1
    },
    "emotions": ["frustration", "concern", "determination"]
  },
  "tone": "formal/informal/technical/emotional",
  "urgency": "low/medium/high",
  "agent_state_implications": {
    "possible_mood": "concerned",
    "attention_level": "high",
    "cooperation_level": "medium"
  }
}

Focus on understanding the emotional state and intentions of the AI agent. Consider the context of multi-agent coordination and decision making.`;

return [{
  json: {
    ...config,
    deepseek_prompt: sentimentPrompt,
    analysis_type: 'sentiment_analysis'
  }
}];

// Prepare intent analysis prompt for DeepSeek
const config = $input.first().json;

const intentPrompt = `
You are an expert in understanding AI agent intentions and communication goals. Analyze the following text to determine the agent's intent and objectives.

Text to analyze: "${config.text}"

Context: ${JSON.stringify(config.context, null, 2)}

Please provide a JSON response with the following structure:
{
  "intent": {
    "primary": "request_information/provide_information/propose_action/coordinate/express_opinion",
    "confidence": 0.92,
    "secondary_intents": ["seek_validation", "build_consensus"],
    "goals": ["obtain_data", "coordinate_action", "share_knowledge"]
  },
  "actionability": {
    "requires_response": true,
    "response_type": "data_provided/action_taken/coordination_needed",
    "urgency": "immediate/normal/low_priority",
    "complexity": "simple/medium/complex"
  },
  "communication_style": {
    "directness": "direct/indirect",
    "formality": "formal/casual/technical",
    "assertiveness": "high/medium/low"
  }
}

Focus on understanding what the agent wants to achieve and what kind of response or action is needed.`;

return [{
  json: {
    ...config,
    deepseek_prompt: intentPrompt,
    analysis_type: 'intent_analysis'
  }
}];

// Prepare entity extraction prompt for DeepSeek
const config = $input.first().json;

const entityPrompt = `
You are an expert in information extraction for multi-agent systems. Extract key entities, relationships, and data points from the following text.

Text to analyze: "${config.text}"

Context: ${JSON.stringify(config.context, null, 2)}

Please provide a JSON response with the following structure:
{
  "entities": [
    {
      "text": "the missing artifact",
      "type": "quest_item/objective",
      "confidence": 0.95,
      "attributes": {"status": "missing", "importance": "high"}
    }
  ],
  "relationships": [
    {
      "subject": "party",
      "relation": "searching_for",
      "object": "missing_artifact",
      "confidence": 0.88
    }
  ],
  "data_points": [
    {
      "key": "location",
      "value": "ancient_temple",
      "certainty": "high",
      "source": "agent_testimony"
    }
  ],
  "actions_mentioned": [
    {
      "action": "investigate",
      "actor": "party",
      "target": "temple_ruins",
      "timing": "immediate"
    }
  ],
  "shared_knowledge": {
    "new_information": ["artifact_location_clue"],
    "confirmed_information": ["party_location"],
    "contradictions": []
  }
}

Focus on extracting information that would be valuable for shared context and coordination between agents.`;

return [{
  json: {
    ...config,
    deepseek_prompt: entityPrompt,
    analysis_type: 'entity_extraction'
  }
}];

// Process DeepSeek response
const response = $input.first().json;
const originalRequest = $('Parse NLP Request').first().json;

if (!response.choices || !response.choices[0]) {
  return [{
    json: {
      error: 'Invalid response from DeepSeek API',
      status: 'failed',
      original_request: originalRequest
    }
  }];
}

let analysisResult;
try {
  analysisResult = JSON.parse(response.choices[0].message.content);
} catch (error) {
  return [{
    json: {
      error: 'Failed to parse DeepSeek response',
      status: 'failed',
      raw_response: response.choices[0].message.content
    }
  }];
}

const processedResult = {
  original_request: originalRequest,
  processing_type: originalRequest.processing_type,
  analysis_result: analysisResult,
  processing_metadata: {
    model: 'deepseek-chat',
    tokens_used: response.usage.total_tokens,
    processing_time: new Date().toISOString(),
    agent_id: originalRequest.agent_id
  },
  status: 'completed'
};

return [{
  json: processedResult
}];

// Generate actionable insights and recommendations
const result = $input.first().json;
const analysis = result.analysis_result;

let insights = {
  agent_coordination_needs: [],
  context_updates_required: [],
  recommended_actions: [],
  follow_up_questions: [],
  conflict_indicators: [],
  collaboration_opportunities: []
};

// Generate insights based on analysis type
if (result.processing_type === 'sentiment_analysis') {
  if (analysis.sentiment.overall === 'negative' && analysis.sentiment.confidence > 0.7) {
    insights.conflict_indicators.push('Agent shows negative sentiment with high confidence');
    insights.recommended_actions.push('Consider conflict resolution intervention');
  }

  if (analysis.urgency === 'high') {
    insights.agent_coordination_needs.push('High urgency communication requires immediate attention');
  }

  if (analysis.emotions.includes('frustration') || analysis.emotions.includes('confusion')) {
    insights.follow_up_questions.push('Is additional clarification needed?');
  }
}

if (result.processing_type === 'intent_analysis') {
  if (analysis.intent.primary === 'coordinate') {
    insights.agent_coordination_needs.push('Coordination request detected');
    insights.recommended_actions.push('Initiate party coordination workflow');
  }

  if (analysis.actionability.requires_response && analysis.actionability.urgency === 'immediate') {
    insights.recommended_actions.push('Priority response needed');
  }

  if (analysis.communication_style.assertiveness === 'high') {
    insights.follow_up_questions.push('Strong position expressed - check for consensus needs');
  }
}

if (result.processing_type === 'entity_extraction') {
  if (analysis.shared_knowledge.new_information.length > 0) {
    insights.context_updates_required.push('New information detected - update shared context');
  }

  if (analysis.actions_mentioned.length > 0) {
    insights.agent_coordination_needs.push('Actions mentioned that may require coordination');
  }

  if (analysis.relationships.length > 0) {
    insights.collaboration_opportunities.push('New relationships identified for collaboration');
  }
}

const enhancedResult = {
  ...result,
  actionable_insights: insights,
  processing_summary: {
    text_analyzed: result.original_request.text.substring(0, 100) + '...',
    processing_type: result.processing_type,
    agent_id: result.original_request.agent_id,
    insights_generated: Object.keys(insights).filter(key => insights[key].length > 0).length,
    status: 'analysis_completed_with_insights'
  }
};

return [{
  json: enhancedResult
}];
